export const PATTERNS_ANALOGIES_ACTIVITIES = [
{n:1,type:"mcq",micro:"Mengapa pola membantu",q:"Menemukan pola dalam sebuah masalah membantu karena...",options:["Kalau kita tahu aturannya, kita bisa memperkirakan bagian yang belum terlihat tanpa mengeceknya satu per satu","Pola tidak pernah berguna untuk memecahkan masalah, karena setiap masalah selalu harus dihitung dari awal","Membuat masalah terlihat lebih rumit, sehingga kita perlu mengecek bagian yang belum terlihat satu per satu"],answer:0,explain:"Pola adalah aturan yang berulang. Kalau kita menangkap aturannya, kita bisa melompat ke jawaban tanpa menghitung semua langkah.",hint:"Kalau kamu tahu tiap gambar bertambah 3 titik, perlukah kamu menggambar semua sampai gambar ke-100?"},
{n:2,type:"mcq",micro:"Apa itu analogi",q:"'Analogi' dalam memecahkan masalah berarti...",options:["Menyerah pada masalah","Menyelesaikan masalah baru dengan meniru cara masalah lain yang bentuknya mirip","Menebak secara acak"],answer:1,explain:"Analogi menghubungkan masalah baru dengan masalah lama yang sudah kamu tahu cara menyelesaikannya.",hint:"'Ini seperti ... yang pernah kukerjakan.'"},
{n:3,type:"mcq",micro:"Melanjutkan pola bilangan",q:"Lanjutkan pola: 2, 4, 6, 8, ...",options:["12","9","10"],answer:2,explain:"Polanya bertambah 2 setiap langkah, jadi setelah 8 adalah 10.",hint:"Berapa selisih antara angka-angka yang berdekatan?"},
{n:4,type:"mcq",micro:"Melanjutkan pola bentuk",q:"Pola: lingkaran, segitiga, lingkaran, segitiga, lingkaran, ... Bentuk berikutnya?",options:["Segitiga","Lingkaran","Persegi"],answer:0,explain:"Pola berselang-seling lingkaran-segitiga, jadi setelah lingkaran adalah segitiga.",hint:"Dua bentuk bergantian terus-menerus."},
{n:5,type:"mcq",micro:"Pola kali",q:"Pola: 3, 6, 12, 24, ... Bilangan berikutnya?",options:["36","48","30"],answer:1,explain:"Setiap bilangan dikali 2, jadi setelah 24 adalah 48.",hint:"Bukan ditambah tetap — coba lihat apakah dikali."},
{n:6,type:"mcq",micro:"Analogi sederhana",q:"'Sarung tangan untuk tangan, seperti kaus kaki untuk ...'",options:["Perut","Kepala","Kaki"],answer:2,explain:"Sarung tangan menutupi tangan; yang menutupi kaki dengan cara serupa adalah kaus kaki.",hint:"Bagian tubuh mana yang 'dibungkus' seperti tangan dibungkus sarung tangan?"},
{n:7,type:"mcq",micro:"Pola dalam masalah",q:"Kamu menyadari setiap Senin pagi kelas selalu kekurangan spidol. Menemukan pola waktu ini membantu karena...",options:["Kamu bisa menyiapkan spidol cadangan khusus Senin, bukan menunggu masalah muncul","Pola itu tidak berarti apa-apa, hanya kebetulan saja, sehingga kamu tidak perlu menyiapkan apa pun","Kamu harus mengganti hari Senin menjadi hari lain supaya spidol di kelas tidak lagi kekurangan"],answer:0,explain:"Pola dalam kapan masalah muncul menunjuk ke penyebab dan memungkinkan pencegahan.",hint:"Kalau sesuatu selalu terjadi di waktu yang sama, apa yang bisa kamu siapkan?"},
{n:8,type:"order",micro:"Menggunakan pola untuk menjawab",q:"Urutkan langkah memakai pola untuk menjawab 'berapa titik pada gambar ke-20' bila gambar 1 = 1 titik, gambar 2 = 4, gambar 3 = 7.",items:["Cari selisih antar gambar: 4−1 = 3, 7−4 = 3, jadi bertambah 3 tiap gambar","Tulis aturannya: titik = 1 + 3 × (nomor gambar − 1)","Masukkan nomor 20: 1 + 3 × 19 = 1 + 57 = 58"],answer:[0,1,2],explain:"Temukan aturan penambahan → tulis rumus → masukkan angka yang ditanya.",hint:"Kamu perlu tahu 'bertambah berapa' sebelum bisa menulis aturannya."},
{n:9,type:"mcq",micro:"Analogi antar masalah",q:"Masalah A: membagi 12 kue ke 4 anak sama rata. Masalah B: membagi 20 kelereng ke 5 anak sama rata. Kedua masalah ini...",options:["Sama sekali berbeda","Punya struktur yang sama (pembagian rata), jadi cara menyelesaikannya sama: bagi jumlah benda dengan jumlah anak","Tidak bisa diselesaikan"],answer:1,explain:"Mengenali bahwa dua masalah punya struktur sama berarti kamu bisa memakai metode yang sama.",hint:"Apa 'bentuk' kedua masalah, terlepas dari benda dan angkanya?"},
{n:10,type:"mcq",micro:"Pola yang salah ditebak",q:"Pola: 1, 2, 4, ... Seseorang menebak berikutnya 8 (dikali 2), yang lain menebak 7 (selisih 1, 2, 3, ...). Ini menunjukkan...",options:["Pola tidak pernah bisa ditebak, sehingga dua orang itu sama-sama tidak mungkin menebak berikutnya","Kedua orang itu pasti salah, karena angka berikutnya hanya boleh ditentukan oleh guru yang membuat polanya","Satu pola bisa punya lebih dari satu aturan yang cocok dengan awalnya; butuh lebih banyak data untuk memastikan"],answer:2,explain:"Beberapa angka awal bisa cocok dengan beberapa aturan berbeda. Lebih banyak contoh membantu memilih aturan yang benar.",hint:"Apakah '1, 2, 4' hanya bisa berlanjut satu cara?"},
{n:11,type:"tf",micro:"Pola perlu dicek",q:"Benar atau Salah: Setelah menebak sebuah pola, sebaiknya kamu mengujinya pada contoh yang belum kamu pakai untuk menemukannya.",answer:true,explain:"Menguji pola pada data baru mengurangi risiko salah tebak. Kalau prediksi cocok, keyakinanmu bertambah.",hint:"Kalau kamu menebak aturan dari 3 angka, bagaimana kamu tahu aturan itu benar?"},
{n:12,type:"tf",micro:"Analogi selalu sempurna",q:"Benar atau Salah: Kalau dua masalah tampak mirip, cara menyelesaikan yang satu pasti bisa dipakai persis untuk yang lain tanpa penyesuaian.",answer:false,explain:"Analogi membantu memberi arah, tapi ada perbedaan yang perlu diperhatikan. Meniru buta bisa menyesatkan.",hint:"Apakah dua masalah yang mirip selalu sama dalam semua hal?"},
{n:13,type:"mcq",micro:"Pola dalam kesalahan",q:"Kamu memeriksa PR matematika dan melihat semua soal yang salah melibatkan pengurangan dengan meminjam. Pola ini menunjukkan...",options:["Ada satu keterampilan spesifik (meminjam) yang perlu dilatih, bukan 'matematika' secara umum","PR-nya terlalu sulit","Kebetulan saja"],answer:0,explain:"Pola dalam jenis kesalahan mengarahkan latihan ke titik yang tepat.",hint:"Apa kesamaan semua soal yang salah?"},
{n:14,type:"mcq",micro:"Analogi untuk menjelaskan",q:"Menjelaskan 'jaringan komputer' sebagai 'seperti jalan raya yang menghubungkan rumah-rumah' adalah contoh memakai analogi untuk...",options:["Menghindari penjelasan yang panjang dengan cara tidak menyebutkan apa pun tentang jaringan komputer itu","Membuat ide yang asing jadi lebih mudah dipahami lewat sesuatu yang sudah dikenal","Membingungkan pendengar dengan benda-benda yang tidak ada hubungannya dengan jaringan komputer sama sekali"],answer:1,explain:"Analogi yang baik menjembatani dari yang dikenal ke yang baru.",hint:"Mengapa membandingkan hal baru dengan hal yang sudah akrab?"},
{n:15,type:"mcq",micro:"Pola tumbuh",q:"Tumpukan: baris 1 = 1 batu, baris 2 = 3, baris 3 = 5, baris 4 = 7. Pola jumlah batu per baris adalah...",options:["Bilangan genap","Selalu bertambah 3","Bilangan ganjil berurutan"],answer:2,explain:"1, 3, 5, 7 adalah bilangan ganjil; tiap baris bertambah 2.",hint:"Angka apa saja itu: 1, 3, 5, 7?"},
{n:16,type:"mcq",micro:"Melihat pola dengan tabel",q:"Cara yang paling membantu untuk menemukan pola dalam data 'jumlah kursi vs jumlah meja' adalah...",options:["Membuat tabel: 1 meja → ? kursi, 2 meja → ? kursi, dan seterusnya, lalu lihat perubahannya","Menghafal semua angka","Menebak"],answer:0,explain:"Tabel menyusun data secara teratur sehingga pola perubahan mudah terlihat.",hint:"Bagaimana kamu menaruh data berpasangan supaya polanya kelihatan?"},
{n:17,type:"mcq",micro:"Analogi struktur cerita",q:"Kamu tahu cara menyelesaikan 'A lebih tua 3 tahun dari B; jumlah umur mereka 21; berapa umur masing-masing?'. Masalah 'panjang tali A 3 m lebih dari tali B; total 21 m; berapa panjang masing-masing?' adalah...",options:["Masalah yang benar-benar baru, sehingga kamu harus mencari cara penyelesaian yang sama sekali berbeda dari umur","Analogi langsung — struktur dan langkah penyelesaiannya identik, hanya 'umur' diganti 'panjang'","Masalah yang tidak bisa diselesaikan dengan cara yang sama, karena yang dicari adalah panjang bukan umur"],answer:1,explain:"Mengenali struktur yang identik memungkinkan kamu memakai langkah yang sudah kamu kuasai.",hint:"Ganti kata 'umur' dengan 'panjang' — apakah langkahnya berubah?"},
{n:18,type:"mcq",micro:"Pola berulang (siklus)",q:"Hari ini Selasa. Pola hari berulang tiap 7 hari. 100 hari lagi hari apa? Cara memakai pola:",options:["Tebak saja","Hitung satu per satu 100 kali","Hitung sisa 100 ÷ 7 = 14 sisa 2; maju 2 hari dari Selasa → Kamis"],answer:2,explain:"Pola siklus memungkinkan memakai sisa bagi (modulo) untuk melompat jauh tanpa menghitung tiap langkah.",hint:"Setelah 7 hari kembali ke hari yang sama — jadi yang penting sisa baginya."},
{n:19,type:"mcq",micro:"Pola sebagai dugaan",q:"Setelah menemukan pola dari beberapa contoh, statusnya adalah...",options:["Dugaan (konjektur) yang kuat tapi masih bisa salah untuk kasus yang belum dicoba","Tidak berguna","Kebenaran mutlak"],answer:0,explain:"Pola dari contoh adalah dugaan. Untuk memastikan berlaku selalu, kadang butuh alasan/pembuktian, bukan hanya lebih banyak contoh.",hint:"Apakah 3 contoh yang cocok membuktikan aturan berlaku untuk semua bilangan?"},
{n:20,type:"open",micro:"Menemukan dan memakai pola",q:"Sebuah pola gambar: gambar 1 punya 4 batang korek, gambar 2 punya 7, gambar 3 punya 10 (tiap gambar menambah satu 'kotak'). Temukan aturannya dan hitung berapa batang untuk gambar ke-15. Tunjukkan caramu.",explain:"Jawaban baik: temukan penambahan tetap, tulis aturan, uji pada contoh yang diketahui, lalu terapkan.",hint:"Cari 'bertambah berapa', tulis rumus, cek dengan gambar 2 dan 3, baru masukkan 15.",sample:"Selisih: 7−4 = 3, 10−7 = 3 → bertambah 3 tiap gambar. Aturan: batang = 4 + 3 × (nomor − 1), atau sama dengan 3 × nomor + 1. Cek: gambar 2 → 3×2+1 = 7 ✓; gambar 3 → 3×3+1 = 10 ✓. Gambar 15 → 3×15 + 1 = 46 batang."},
{n:21,type:"mcq",micro:"Struktur vs permukaan",q:"Dua soal cerita: satu tentang 'kelinci di kandang', satu tentang 'buku di rak'. Keduanya menanyakan 'berapa total bila ada 6 kelompok berisi 8'. 'Permukaan' berbeda, tetapi...",options:["Struktur dalamnya juga berbeda","'Struktur dalam'-nya sama: 6 × 8","Tidak ada hubungannya"],answer:1,explain:"Pemecah masalah yang terampil melihat menembus 'baju' cerita ke struktur matematisnya.",hint:"Abaikan kelinci dan buku — operasi apa yang dibutuhkan?"},
{n:22,type:"mcq",micro:"Transfer keterampilan",q:"'Transfer' terjadi ketika kamu...",options:["Menyalin jawaban teman","Memindahkan barang","Menggunakan cara yang dipelajari di satu situasi untuk memecahkan masalah di situasi yang berbeda"],answer:2,explain:"Transfer adalah tujuan belajar memecahkan masalah: cara yang kamu kuasai jadi alat untuk masalah-masalah baru.",hint:"Belajar sesuatu di satu tempat, memakainya di tempat lain."},
{n:23,type:"mcq",micro:"Menyederhanakan lalu generalisasi",q:"Untuk 'jumlah 1 + 2 + 3 + ... + 100', strategi pola:",options:["Coba 1+2+3+4 dan 1+...+6 dulu, cari pola/trik (pasangkan ujung-ujung), lalu terapkan ke 100","Tebak angka besar","Jumlahkan satu per satu selama sejam"],answer:0,explain:"Menyelesaikan versi kecil sering mengungkap trik (di sini: pasangkan 1+100, 2+99, ... = 50 pasang × 101) yang berlaku untuk versi besar.",hint:"Apa yang kamu temukan kalau menjumlahkan 1 sampai 6 dengan memasangkan ujungnya?"},
{n:24,type:"classify",micro:"Masalah dengan struktur sama",q:"Kelompokkan masalah berdasarkan struktur: 'Pembagian rata', 'Penambahan berulang (perkalian)', atau 'Selisih & total (dua yang tak diketahui)'.",items:["8 pizza dibagi 4 orang sama rata","5 kotak masing-masing 6 apel, berapa total apel","Kakak 4 tahun lebih tua dari adik, jumlah umur 20, cari umur masing-masing","24 permen dibagi rata untuk 6 anak"],groups:["Pembagian rata","Penambahan berulang (perkalian)","Selisih & total"],answer:{"Pembagian rata":["8 pizza dibagi 4 orang sama rata","24 permen dibagi rata untuk 6 anak"],"Penambahan berulang (perkalian)":["5 kotak masing-masing 6 apel, berapa total apel"],"Selisih & total":["Kakak 4 tahun lebih tua dari adik, jumlah umur 20, cari umur masing-masing"]},explain:"Masalah dengan struktur sama diselesaikan dengan metode sama, meski ceritanya berbeda.",hint:"Abaikan benda dalam cerita; lihat operasi/pola yang dibutuhkan."},
{n:25,type:"mcq",micro:"Analogi yang menyesatkan",q:"'Belajar bahasa itu seperti mengisi ember: guru menuang, murid menampung.' Analogi ini bisa menyesatkan karena...",options:["Ember memang tidak ada di dalam kelas, sehingga analogi itu tidak berlaku dan tidak perlu dipikirkan","Belajar sebenarnya aktif — murid membangun pemahaman, tidak sekadar menampung; analogi 'menanam benih' mungkin lebih tepat","Analogi tidak pernah salah, sehingga belajar bahasa memang hanya soal guru menuangkan ilmu kepada murid"],answer:1,explain:"Analogi menyoroti sebagian sifat dan menyembunyikan yang lain. Menyadari batas analogi mencegah kesimpulan keliru.",hint:"Apakah murid pasif seperti ember, atau aktif membangun sesuatu?"},
{n:26,type:"mcq",micro:"Mencari 'kasus yang sudah dipecahkan'",q:"Menghadapi masalah geometri yang sulit, pertanyaan analogi yang berguna:",options:["'Apakah aku sebenarnya suka pelajaran geometri, atau lebih suka pelajaran lain yang jauh lebih mudah?'","'Berapa lama waktu ujian geometri ini berlangsung, dan kapan guru akan mengumpulkan semua lembar jawabannya?'","'Adakah bangun yang lebih sederhana (segitiga, persegi) yang bisa kubuat dari bangun ini, yang rumusnya sudah kutahu?'"],answer:2,explain:"Memecah bangun rumit menjadi bangun sederhana yang sudah dikenal adalah bentuk analogi/transfer.",hint:"Bangun apa yang rumusnya sudah kamu hafal?"},
{n:27,type:"mcq",micro:"Pola dalam data eksperimen",q:"Dalam percobaan, tinggi tanaman tiap minggu: 2, 5, 8, 11 cm. Prediksi minggu ke-6 dengan pola:",options:["Sekitar 20 cm (bertambah 3 tiap minggu: 11, 14, 17, 20)","100 cm","Tidak bisa diprediksi"],answer:0,explain:"Pola linear (bertambah tetap) memungkinkan prediksi — dengan catatan pertumbuhan nyata bisa melambat nanti.",hint:"Bertambah berapa tiap minggu, dan berapa minggu lagi dari minggu 4 ke minggu 6?"},
{n:28,type:"mcq",micro:"Batas ekstrapolasi pola",q:"Melanjutkan pola tinggi tanaman '2, 5, 8, 11, ...' sampai minggu ke-100 memberi 299 cm. Ini kemungkinan tidak realistis karena...",options:["Tanaman memang tidak tumbuh sama sekali, sehingga tinggi pada minggu ke-100 pasti tetap sama dengan awal","Pola matematis tidak selalu berlaku selamanya di dunia nyata; pertumbuhan tanaman akan melambat/berhenti","Perhitungannya pasti salah, karena menambah 3 cm setiap minggu tidak mungkin menghasilkan angka sebesar itu"],answer:1,explain:"Pola berguna untuk memprediksi dekat data yang kita punya, tapi memaksakannya jauh ke luar sering keliru.",hint:"Apakah tanaman tumbuh dengan laju tetap selamanya?"},
{n:29,type:"mcq",micro:"Analogi lintas bidang",q:"Cara mengatur buku di rak (kelompokkan sejenis, beri label, yang sering dipakai di depan) bisa dipindah ke masalah...",options:["Menghitung luas segitiga","Tidak ada","Mengatur berkas di komputer, atau menata alat di laci — struktur 'pengorganisasian' yang sama"],answer:2,explain:"Prinsip pengorganisasian yang sama berlaku untuk banyak masalah 'menata benda agar mudah ditemukan'.",hint:"Masalah lain apa yang intinya 'menata supaya mudah dicari'?"},
{n:30,type:"order",micro:"Menyederhanakan untuk menemukan pola",q:"Urutkan langkah strategi 'sederhanakan lalu generalisasi'.",items:["Buat versi masalah dengan angka jauh lebih kecil","Selesaikan beberapa versi kecil dan catat hasilnya","Cari pola atau trik yang menghubungkan masukan dengan hasil","Uji pola pada satu versi kecil lain, lalu terapkan ke masalah asli"],answer:[0,1,2,3],explain:"Perkecil → selesaikan beberapa → cari pola → uji lalu terapkan ke versi penuh.",hint:"Kamu butuh beberapa hasil kecil sebelum bisa mencari pola di antaranya."},
{n:31,type:"mcq",micro:"Pola dalam bentuk berbeda",q:"Pola '2, 4, 8, 16' (kali 2) dan pola 'bakteri membelah tiap jam' ...",options:["Adalah pola yang sama (penggandaan) muncul dalam konteks berbeda","Tidak berhubungan","Keduanya penambahan tetap"],answer:0,explain:"Pola penggandaan (eksponensial) muncul di banyak tempat: bakteri, lipatan kertas, bunga majemuk. Mengenalinya membantu memprediksi.",hint:"Apa yang terjadi pada jumlahnya setiap langkah — ditambah tetap atau dikali tetap?"},
{n:32,type:"mcq",micro:"Menggunakan analogi dengan hati-hati",q:"Setelah memakai analogi untuk mendapat ide solusi, langkah bijak berikutnya:",options:["Langsung terapkan tanpa memeriksa","Periksa di mana masalah barumu BERBEDA dari yang lama, dan sesuaikan solusinya untuk perbedaan itu","Buang analoginya"],answer:1,explain:"Analogi memberi titik awal; menyesuaikan untuk perbedaan membuat solusi benar-benar cocok.",hint:"Bagian mana dari masalah baru yang tidak dicakup oleh masalah lama?"},
{n:33,type:"tf",micro:"Pola bisa ditemukan lewat gambar",q:"Benar atau Salah: Cara menuliskan atau menggambarkan sekumpulan bilangan tidak berpengaruh sama sekali pada seberapa mudah polanya terlihat.",answer:false,explain:"Representasi sangat berpengaruh. Contoh: menyusun titik 1, 3, 6, 10 sebagai tumpukan segitiga langsung menunjukkan mereka 'bilangan segitiga', yang tak kentara dari daftar biasa.",hint:"Apakah 1, 3, 6, 10 lebih bermakna sebagai daftar atau sebagai tumpukan segitiga?"},
{n:34,type:"mcq",micro:"Analogi negatif (perbedaan penting)",q:"'Menabung uang itu seperti menyimpan makanan di kulkas.' Perbedaan penting yang membuat analogi ini pincang:",options:["Tidak ada perbedaan","Kulkas tidak ada di bank","Makanan membusuk seiring waktu, sedangkan uang di rekening bisa tumbuh (bunga) atau menyusut nilainya (inflasi) — bukan sekadar 'awet'"],answer:2,explain:"Setiap analogi punya titik di mana ia berhenti berlaku. Mengenali titik itu mencegah kesimpulan salah.",hint:"Apa yang terjadi pada uang seiring waktu yang tidak terjadi pada makanan beku?"},
{n:35,type:"mcq",micro:"Pola dalam perilaku",q:"Kamu memperhatikan: setiap kali begadang, besoknya kamu mudah marah dan sulit fokus. Pola ini berguna karena...",options:["Memberi hubungan sebab-akibat yang bisa kamu uji dan ubah (tidur cukup → cek apakah suasana hati membaik)","Tidak berarti apa-apa karena begadang dan suasana hati tidak mungkin berhubungan satu sama lain sama sekali","Berarti kamu harus berhenti sekolah supaya tidak perlu begadang mengerjakan tugas yang sangat banyak lagi"],answer:0,explain:"Pola dalam pengalaman pribadi adalah data untuk memahami dan memperbaiki kebiasaan.",hint:"Apa yang selalu mendahului hari-hari burukmu?"},
{n:36,type:"mcq",micro:"Generalisasi terlalu cepat",q:"Setelah 2 kali toko A memberi kembalian salah, kamu menyimpulkan 'semua kasir toko A tidak becus'. Kelemahannya:",options:["Kesimpulannya pasti benar","2 kejadian adalah sampel kecil; bisa jadi kebetulan atau satu kasir tertentu — perlu lebih banyak pengamatan","Tidak ada kelemahan"],answer:1,explain:"Menemukan 'pola' dari sedikit contoh berisiko. Generalisasi butuh cukup data dan pertimbangan penyebab lain.",hint:"Apakah 2 kali cukup untuk menyimpulkan tentang 'semua'?"},
{n:37,type:"mcq",micro:"Analogi untuk memilih strategi",q:"'Masalah ini terasa seperti mencari kata di kamus.' Analogi ini menyarankan strategi...",options:["Menyerah","Membaca seluruh kamus","Pencarian dengan membagi wilayah (buka di tengah, sesuaikan) daripada memeriksa satu per satu dari awal"],answer:2,explain:"Analogi yang tepat langsung menyarankan strategi yang terbukti untuk masalah sejenis.",hint:"Bagaimana kamu mencari kata di kamus dengan cepat?"},
{n:38,type:"mcq",micro:"Pola yang tidak ada",q:"Melempar koin 5 kali dan mendapat A-A-A-G-A, lalu yakin 'setelah 3 A pasti G'. Ini adalah...",options:["Melihat pola pada sesuatu yang sebenarnya acak; tiap lemparan tetap 50-50, tidak dipengaruhi lemparan sebelumnya","Bukti bahwa koin itu curang dan sengaja dibuat lebih sering jatuh pada sisi A dibandingkan sisi G","Pola nyata yang bisa dipercaya, sehingga setelah tiga A pada lemparan berikutnya pasti muncul sisi G"],answer:0,explain:"Manusia cenderung 'melihat' pola bahkan dalam keacakan. Menyadari ini penting agar tidak salah menyimpulkan.",hint:"Apakah koin 'ingat' hasil lemparan sebelumnya?"},
{n:39,type:"mcq",micro:"Menggunakan beberapa analogi",q:"Untuk memahami masalah baru yang rumit, memakai 2–3 analogi berbeda...",options:["Membingungkan, pakai satu saja","Bisa membantu — tiap analogi menyoroti sisi berbeda dari masalah, dan bersama-sama memberi gambaran lebih lengkap","Selalu buruk"],answer:1,explain:"Analogi yang berbeda menerangi aspek berbeda. Menggabungkannya (sambil sadar batas masing-masing) memperkaya pemahaman.",hint:"Bisakah satu analogi menangkap semua sisi masalah yang rumit?"},
{n:40,type:"open",micro:"Memakai analogi untuk memecahkan masalah",q:"Masalah baru: 'Bagaimana mengatur giliran 6 kelompok memakai 1 mikroskop dalam 1 jam pelajaran secara adil?' Temukan masalah lain yang kamu tahu cara menyelesaikannya yang STRUKTURNYA mirip, jelaskan kemiripannya, dan pindahkan solusinya.",explain:"Jawaban baik: menyebut masalah analog nyata, menjelaskan kesamaan struktur (banyak pengguna–satu sumber daya–adil), memindahkan solusi, dan menyesuaikan untuk perbedaan.",hint:"Masalah 'banyak orang berbagi satu benda secara adil' muncul di banyak tempat.",sample:"Masalah mirip: mengatur giliran memakai satu ayunan di taman, atau menjadwalkan pemakaian satu kamar mandi untuk banyak orang di pagi hari. Struktur sama: banyak pengguna, satu sumber daya, waktu terbatas, ingin adil. Solusi yang dipindahkan: bagi 60 menit menjadi 6 slot @ 10 menit; buat daftar urutan (undi agar adil); pasang timer/pengingat; kelompok yang menunggu mengerjakan tugas lain (mencatat, menggambar hasil). Penyesuaian: sisakan 2 menit transisi antar kelompok, jadi slot efektif 8 menit."},
{n:41,type:"mcq",micro:"Merumuskan aturan pola",q:"Pola meja-kursi: 1 meja → 4 kursi, 2 meja (disambung) → 6 kursi, 3 meja → 8 kursi. Aturan untuk n meja:",options:["kursi = n + 3","kursi = 4n","kursi = 2n + 2"],answer:2,explain:"Cek: n=1 → 4 ✓; n=2 → 6 ✓; n=3 → 8 ✓. Tiap meja tambahan menambah 2 kursi (sisi panjang), plus 2 di ujung.",hint:"Bertambah 2 tiap meja → 2n bagian, lalu sesuaikan agar n=1 memberi 4."},
{n:42,type:"mcq",micro:"Memetakan bagian analogi",q:"Analogi 'aliran listrik seperti aliran air': tegangan ↔ tekanan air, arus ↔ debit air, hambatan ↔ ...",options:["Sempitnya pipa (yang menahan aliran)","Panjang sungai saja","Warna pipa"],answer:0,explain:"Analogi yang baik memetakan tiap bagian: hambatan listrik seperti pipa sempit yang menahan aliran air.",hint:"Apa yang membuat air mengalir lebih sulit dalam pipa?"},
{n:43,type:"mcq",micro:"Pola berulang dengan sisa",q:"Manik-manik berpola merah, hijau, biru, kuning berulang. Manik ke-27 warnanya?",options:["Merah (27 ÷ 4 = 6 sisa 3 → warna ke-3... periksa: sisa 3 = biru)","Biru (sisa 3 dari pola merah-hijau-biru-kuning)","Kuning"],answer:1,explain:"27 ÷ 4 = 6 sisa 3. Sisa 3 menunjuk warna ketiga dalam pola: biru.",hint:"Bagi 27 dengan panjang pola (4); sisa baginya menunjuk posisi dalam satu putaran."},
{n:44,type:"mcq",micro:"Analogi untuk memodelkan",q:"Untuk memperkirakan berapa lama antrean kantin, memodelkannya seperti 'air mengalir dari keran ke ember bocor' berguna karena...",options:["Kantin tidak seperti ember sama sekali, sehingga perumpamaan itu tidak membantu menghitung panjang antrean","Model seperti itu tidak membantu, karena panjang antrean hanya bisa diketahui dengan menunggu seharian","Kedatangan orang = air masuk, pelayanan = air keluar; kalau masuk lebih cepat dari keluar, antrean (isi ember) bertambah"],answer:2,explain:"Model aliran masuk vs keluar adalah analogi kuat untuk banyak masalah antrean dan penumpukan.",hint:"Kapan antrean memanjang: saat orang datang lebih cepat atau lebih lambat dari dilayani?"},
{n:45,type:"mcq",micro:"Pola kuadratik sederhana",q:"Titik pada pola: gambar 1 → 1, gambar 2 → 4, gambar 3 → 9, gambar 4 → 16. Aturannya:",options:["titik = nomor × nomor (kuadrat)","titik = nomor + 3","titik = nomor × 2"],answer:0,explain:"1, 4, 9, 16 adalah bilangan kuadrat: 1², 2², 3², 4². Aturan: titik = n².",hint:"Apa hubungan 4 dengan 2, dan 9 dengan 3?"},
{n:46,type:"mcq",micro:"Transfer terarah",q:"'Transfer terarah' berarti kamu...",options:["Menyalin tugas","Sengaja bertanya 'prinsip apa dari yang kupelajari sebelumnya yang berlaku di sini?' alih-alih menunggu ide datang sendiri","Memindahkan meja"],answer:1,explain:"Transfer sering tidak terjadi otomatis. Secara sadar mencari koneksi ke pengetahuan lama meningkatkan peluang transfer.",hint:"Apakah kamu menunggu koneksi muncul, atau aktif mencarinya?"},
{n:47,type:"mcq",micro:"Menemukan invarian",q:"Dalam banyak teka-teki, mencari 'apa yang TIDAK berubah setiap langkah' (invarian) membantu karena...",options:["Invarian tidak berguna dalam teka-teki, karena yang penting hanyalah mencoba semua kemungkinan langkah satu per satu","Semua hal dalam teka-teki selalu berubah di setiap langkah, sehingga tidak ada yang bisa dijadikan patokan","Kalau sesuatu selalu tetap, keadaan yang melanggarnya pasti mustahil dicapai"],answer:2,explain:"Contoh: kalau tiap langkah menjaga jumlah tetap ganjil, maka keadaan berjumlah genap tidak mungkin dicapai. Invarian adalah alat penalaran pola yang kuat.",hint:"Kalau warna papan catur yang diinjak selalu berganti, bisakah kamu kembali ke titik awal dalam langkah ganjil?"},
{n:48,type:"classify",micro:"Jenis pola",q:"Kelompokkan tiap barisan sebagai 'Penambahan tetap', 'Penggandaan (kali tetap)', atau 'Kuadrat'.",items:["5, 8, 11, 14","3, 6, 12, 24","1, 4, 9, 16","2, 2, 2, ... lalu 10, 20, 40"],groups:["Penambahan tetap","Penggandaan","Kuadrat"],answer:{"Penambahan tetap":["5, 8, 11, 14"],"Penggandaan":["3, 6, 12, 24","2, 2, 2, ... lalu 10, 20, 40"],"Kuadrat":["1, 4, 9, 16"]},explain:"Cek selisih (tetap → penambahan), rasio (tetap → penggandaan), atau apakah tiap suku = posisi² (kuadrat).",hint:"Hitung selisih dan rasio antar suku."},
{n:49,type:"mcq",micro:"Pola pada tabel dua arah",q:"Tabel perkalian: pola bilangan pada diagonal (1, 4, 9, 16, 25) adalah...",options:["Bilangan kuadrat","Bilangan ganjil","Kelipatan 5"],answer:0,explain:"Diagonal tabel perkalian adalah n × n = n², yaitu bilangan kuadrat.",hint:"Sel diagonal adalah baris ke-n dikali kolom ke-n."},
{n:50,type:"mcq",micro:"Analogi yang produktif",q:"Ciri analogi yang PALING berguna untuk memecahkan masalah:",options:["Kemiripan hanya pada penampilan luar, seperti warna dan ukuran, walaupun cara kerja kedua hal itu berbeda","Kemiripan pada STRUKTUR dan HUBUNGAN antar bagian, bukan sekadar penampilan","Berasal dari bidang pelajaran yang sama persis, misalnya sama-sama dari matematika atau sama-sama dari sains"],answer:1,explain:"Analogi permukaan (dua-duanya merah) jarang membantu. Analogi struktural (dua-duanya 'satu sumber, banyak pengguna') memandu solusi.",hint:"Apa yang lebih penting: dua masalah terlihat mirip, atau bekerja dengan cara yang mirip?"},
{n:51,type:"open",micro:"Merumuskan aturan dari pola",q:"Pola batang korek membentuk deretan segitiga yang berbagi sisi: 1 segitiga = 3 batang, 2 segitiga = 5 batang, 3 segitiga = 7 batang, 4 = 9. Rumuskan aturan untuk n segitiga, jelaskan mengapa masuk akal, dan hitung untuk 20 segitiga.",explain:"Jawaban baik: menemukan rumus, memberi alasan struktural (sisi berbagi), dan menerapkannya.",hint:"Segitiga pertama 'mahal' (3), sisanya 'murah' (2) karena berbagi sisi.",sample:"Selisih tetap 2 → batang = 2n + 1. Cek: n=1 → 3 ✓, n=3 → 7 ✓. Mengapa masuk akal: segitiga pertama butuh 3 batang; tiap segitiga tambahan hanya butuh 2 batang baru karena satu sisi dipakai bersama segitiga sebelumnya. Jadi 3 + 2×(n−1) = 2n + 1. Untuk n=20: 2×20 + 1 = 41 batang."},
{n:52,type:"mcq",micro:"Menggeneralisasi solusi",q:"Setelah menyelesaikan 'berapa jabat tangan untuk 5 orang' (= 10), menggeneralisasi berarti...",options:["Mengerjakan ulang untuk tiap jumlah orang","Melupakan hasilnya","Menemukan rumus untuk n orang: n×(n−1)/2, sehingga soal 'berapa untuk 50 orang' langsung terjawab"],answer:2,explain:"Generalisasi mengubah satu jawaban menjadi rumus yang menjawab seluruh keluarga masalah.",hint:"Bagaimana caramu menjawab 'untuk 5', 'untuk 6', 'untuk 100' dengan satu kali kerja?"},
{n:53,type:"mcq",micro:"Pola untuk memeriksa jawaban",q:"Kamu menghitung 1+2+3+...+10 = 55. Cara memakai pola untuk memeriksa:",options:["Pasangkan (1+10), (2+9), ... = 5 pasang × 11 = 55 ✓ — cara kedua yang berbeda menguatkan jawaban","Tidak bisa diperiksa dengan cara apa pun, karena jumlah deret hanya bisa dipercaya dari hitungan pertama saja","Hitung ulang dengan cara yang sama persis dari awal, karena hasil yang sama berarti pasti benar selamanya"],answer:0,explain:"Memeriksa dengan metode berbeda (di sini: trik pasangan) adalah cara kuat memastikan jawaban benar.",hint:"Adakah cara kedua, memakai pola, untuk sampai ke jawaban yang sama?"},
{n:54,type:"mcq",micro:"Analogi lintas mata pelajaran",q:"Konsep 'rantai makanan' dalam biologi dan 'aliran uang dalam ekonomi' punya analogi berupa...",options:["Keduanya tentang hewan","Energi/nilai mengalir dari satu tingkat ke tingkat berikutnya, dengan sebagian 'hilang' di tiap tahap","Tidak ada kesamaan"],answer:1,explain:"Pola 'aliran melalui jaringan bertingkat dengan kehilangan di tiap langkah' muncul di ekologi, ekonomi, dan rekayasa.",hint:"Apa yang mengalir, dan apa yang terjadi di tiap perpindahan?"},
{n:55,type:"mcq",micro:"Ketika analogi harus ditinggalkan",q:"Kamu memakai analogi 'otak seperti komputer' lalu menyimpulkan 'manusia bisa meng-copy-paste ingatan sempurna'. Tindakan tepat:",options:["Cari komputer yang lebih canggih dan lebih cepat, karena kesimpulan itu hanya salah jika komputer yang dibayangkan terlalu lambat dan tua","Pertahankan kesimpulan itu karena analogi 'otak seperti komputer' sudah dipakai banyak orang, sehingga pasti benar dan tidak perlu diperiksa lagi","Kenali bahwa analogi sudah melewati batasnya — ingatan manusia direkonstruksi dan berubah, tidak seperti file — dan tinggalkan kesimpulan itu"],answer:2,explain:"Analogi adalah alat berpikir, bukan bukti. Ketika ia memberi kesimpulan yang bertentangan dengan kenyataan, batasnya sudah tercapai.",hint:"Apakah ingatanmu tentang ulang tahun lima tahun lalu sepersis file foto?"},
{n:56,type:"mcq",micro:"Pola sebagai ringkasan",q:"Menyimpan aturan 'batang = 2n + 1' lebih baik daripada menghafal '3, 5, 7, 9, 11, ...' karena...",options:["Satu aturan pendek menghasilkan tak terhingga nilai dan lebih mudah diingat serta diperiksa","Menghafal daftar selalu lebih baik","Tidak ada bedanya"],answer:0,explain:"Pola/rumus adalah bentuk 'pemadatan': banyak informasi diringkas menjadi aturan singkat.",hint:"Mana yang lebih ringkas: rumus atau daftar tak berujung?"},
{n:57,type:"tf",micro:"Beberapa contoh cocok belum membuktikan",q:"Benar atau Salah: Jika sebuah pola cocok untuk 5 contoh pertama, itu sudah membuktikan pola berlaku untuk semua kasus.",answer:false,explain:"Contoh yang cocok menguatkan dugaan tapi tidak membuktikannya. Ada pola terkenal yang cocok untuk banyak kasus lalu gagal. Kepastian butuh alasan/pembuktian.",hint:"Bisakah sebuah aturan cocok untuk 5, 10, bahkan 40 kasus lalu gagal di kasus ke-41?"},
{n:58,type:"mcq",micro:"Pola dalam strategi permainan",q:"Dalam permainan mengambil 1–3 batang bergiliran, yang mengambil batang terakhir menang. Menemukan pola 'sisakan kelipatan 4 untuk lawan' berarti...",options:["Tidak ada strategi","Kamu menemukan strategi menang dengan menganalisis kasus kecil (sisa 1,2,3 → menang; sisa 4 → kalah) lalu menggeneralisasi","Permainan itu acak"],answer:1,explain:"Menganalisis posisi kecil ('menang' atau 'kalah') lalu mencari pola adalah cara menemukan strategi optimal banyak permainan.",hint:"Posisi mana yang membuatmu kalah, dan apa polanya?"},
{n:59,type:"mcq",micro:"Membangun 'perpustakaan pola'",q:"Manfaat mengingat pola dan analogi yang pernah kamu temui:",options:["Membebani ingatan tanpa guna, karena pola lama tidak akan pernah muncul lagi pada masalah-masalah yang baru","Membuatmu malas berpikir, karena kamu hanya menyalin jawaban lama dan tidak mau memahami masalah yang baru","Menjadi 'kotak alat' — saat menghadapi masalah baru, kamu punya lebih banyak pola untuk dicocokkan"],answer:2,explain:"Pemecah masalah berpengalaman punya banyak 'pola tersimpan' (perkalian = penambahan berulang, aliran masuk-keluar, bagi dua wilayah) yang bisa dipanggil.",hint:"Mengapa orang yang sudah mengerjakan banyak masalah lebih cepat mengenali cara?"},
{n:60,type:"open",micro:"Transfer terarah untuk masalah nyata",q:"Masalah: 'Kelompok belajar kami sering membahas hal yang sama berulang karena tidak ada catatan.' Cari minimal satu prinsip/pola dari pengalaman lain (sekolah, rumah, permainan) yang bisa ditransfer, jelaskan pemetaannya, dan usulkan solusi.",explain:"Jawaban baik: menyebut sumber transfer, memetakan bagian-bagiannya ke masalah baru, dan menurunkan solusi konkret dari pemetaan itu.",hint:"Di mana lagi orang menghadapi 'lupa apa yang sudah dilakukan' dan bagaimana mereka mengatasinya?",sample:"Prinsip transfer: dari cara guru memakai 'papan tulis + rangkuman di akhir pelajaran', atau dari game yang punya 'save point'. Pemetaan: pembahasan kelompok ↔ pelajaran; hal yang sudah dibahas ↔ materi yang sudah diajarkan; lupa & mengulang ↔ tidak ada save. Solusi: tunjuk satu 'notulen' bergiliran tiap sesi yang menulis 3 hal — apa yang dibahas, kesimpulan, dan tugas untuk sesi berikutnya — lalu bagikan ke grup. Sesi berikutnya dibuka dengan membaca catatan itu 2 menit."},
{n:61,type:"mcq",micro:"Pola palsu dari data terpilih",q:"Seseorang menunjukkan '5 atlet sukses yang semuanya sarapan sereal merek X' sebagai bukti sereal itu bikin sukses. Kelemahan pola ini:",options:["Data dipilih untuk mendukung kesimpulan; tidak melihat atlet sukses yang TIDAK makan sereal itu, atau orang yang makan sereal itu tapi tidak sukses","Tidak ada kelemahan","Lima orang cukup untuk membuktikan"],answer:0,explain:"Pola yang dibangun dari contoh terpilih (cherry-picking) menyesatkan. Perlu melihat semua kasus, termasuk yang tidak cocok.",hint:"Apakah kita melihat orang yang makan sereal itu TAPI tidak sukses?"},
{n:62,type:"mcq",micro:"Analogi yang membawa asumsi tersembunyi",q:"'Mengelola negara itu seperti mengelola rumah tangga: kalau utang, harus segera berhemat total.' Asumsi tersembunyi yang perlu diperiksa:",options:["Tidak ada asumsi","Bahwa negara dan rumah tangga bekerja dengan cara ekonomi yang sama persis — padahal skalanya, kemampuannya, dan dampaknya sangat berbeda","Bahwa rumah tangga punya utang"],answer:1,explain:"Analogi yang menarik bisa menyelundupkan asumsi. Selalu tanya: di mana kedua hal ini sebenarnya berbeda?",hint:"Apakah cara sebuah keluarga menangani utang pasti berlaku untuk sistem yang jauh lebih besar dan berbeda?"},
{n:63,type:"tf",micro:"Pola bisa berubah",q:"Benar atau Salah: Pola yang berlaku selama bertahun-tahun bisa berubah bila kondisi yang mendasarinya berubah.",answer:true,explain:"Contoh: pola 'toko ramai tiap Sabtu' bisa berubah setelah ada pusat perbelanjaan baru. Pola bergantung pada penyebabnya.",hint:"Kalau alasan di balik pola menghilang, apa yang terjadi pada pola itu?"},
{n:64,type:"mcq",micro:"Korelasi bukan pola sebab-akibat",q:"Data menunjukkan bulan-bulan dengan penjualan es krim tinggi juga punya kasus tenggelam tinggi. Menyimpulkan 'es krim menyebabkan tenggelam' keliru karena...",options:["Es krim memang berbahaya","Datanya salah","Ada faktor ketiga (cuaca panas) yang menyebabkan keduanya; keduanya berpola bersama tanpa saling menyebabkan"],answer:2,explain:"Dua hal yang berpola bersamaan bisa disebabkan faktor ketiga. Pola bersama ≠ satu menyebabkan yang lain.",hint:"Apa yang membuat orang membeli es krim DAN berenang?"},
{n:65,type:"mcq",micro:"Ekstrapolasi berbahaya",q:"'Nilaiku naik 5 poin tiap ulangan; berarti dalam 10 ulangan lagi aku dapat 130.' Kesalahannya:",options:["Nilai punya batas atas (100); pola linear tidak bisa dilanjutkan melewati batas nyata","Tidak ada kesalahan","Perhitungannya salah"],answer:0,explain:"Pola matematis harus dicek terhadap batas dan kenyataan konteks. Banyak pola melengkung atau berhenti pada titik tertentu.",hint:"Berapa nilai tertinggi yang mungkin?"},
{n:66,type:"tf",micro:"Analogi bisa menyembunyikan perbedaan",q:"Benar atau Salah: Analogi hanya bisa menyoroti kesamaan dan tidak mungkin membuat kita melewatkan perbedaan penting antara dua hal.",answer:false,explain:"Analogi mengarahkan perhatian ke kesamaan, sehingga kalau kita tidak sengaja mencari perbedaan, kita bisa membawa asumsi yang tidak berlaku.",hint:"Ketika kamu bilang 'A seperti B', apa yang mungkin kamu abaikan tentang A?"},
{n:67,type:"mcq",micro:"Pola dari sampel bias",q:"Kamu menyimpulkan 'semua siswa suka pelajaran seni' dari survei yang hanya diisi anggota klub seni. Masalahnya:",options:["Tidak ada masalah","Sampel tidak mewakili — orang yang mengisi sudah cenderung suka seni sejak awal","Survei selalu akurat"],answer:1,explain:"Pola dari kelompok yang bias tidak berlaku untuk populasi lebih luas.",hint:"Siapa yang mengisi survei, dan apakah mereka mewakili semua siswa?"},
{n:68,type:"mcq",micro:"Menguji pola dengan kasus ekstrem",q:"Setelah menemukan aturan pola, mencobanya pada kasus ekstrem (n = 0, n = 1, angka sangat besar) berguna untuk...",options:["Membuang waktu","Membuat aturan lebih rumit","Memeriksa apakah aturan tetap masuk akal di batas-batasnya, sering mengungkap kesalahan"],answer:2,explain:"Kasus batas adalah tempat aturan yang hampir benar sering gagal — ujian yang bagus.",hint:"Apakah rumusmu memberi jawaban masuk akal untuk n = 0?"},
{n:69,type:"mcq",micro:"Analogi antara masalah dan solusi",q:"Bahaya berpikir 'solusi yang berhasil di sekolah lain pasti berhasil di sekolah kita':",options:["Konteks berbeda (jumlah siswa, dana, budaya) bisa membuat solusi yang sama memberi hasil berbeda; perlu penyesuaian dan uji kecil","Tidak ada bahaya sama sekali, jadi tiru saja seluruh solusinya tanpa memeriksa apakah sekolah kita sama atau tidak","Sekolah lain selalu salah dalam memecahkan masalah, jadi solusi mereka pasti tidak boleh dipakai di sekolah kita"],answer:0,explain:"Transfer solusi antar konteks adalah analogi — berguna sebagai titik awal, tapi butuh pemeriksaan perbedaan dan adaptasi.",hint:"Apa yang berbeda antara dua sekolah yang bisa memengaruhi hasil?"},
{n:70,type:"order",micro:"Menilai apakah sebuah pola bisa dipercaya",q:"Urutkan pertanyaan untuk menilai keandalan sebuah pola yang kamu temukan.",items:["Dari berapa banyak contoh, dan apakah contohnya dipilih adil (tidak bias)?","Apakah pola cocok pada contoh baru yang tidak dipakai menemukannya?","Adakah alasan/mekanisme yang menjelaskan MENGAPA pola ini terjadi?","Di kondisi apa pola ini kemungkinan berhenti berlaku?"],answer:[0,1,2,3],explain:"Cek jumlah & keadilan data → uji pada data baru → cari penjelasan sebab → kenali batas berlakunya.",hint:"Mulai dari kualitas data yang menghasilkan pola."},
{n:71,type:"mcq",micro:"Pola yang benar tapi tidak berguna",q:"Kamu menemukan 'setiap soal bernomor genap di buku ini jawabannya lebih panjang'. Meski mungkin pola nyata, ini tidak berguna untuk memecahkan soal karena...",options:["Seharusnya yang dihitung adalah soal bernomor ganjil, karena pola pada soal genap pasti selalu salah semuanya","Tidak membantu kamu MENGERJAKAN soal apa pun; hanya deskripsi tanpa daya prediksi yang berarti","Pola genap-ganjil selalu salah pada semua buku pelajaran, sehingga tidak ada gunanya mencatat pola seperti itu"],answer:1,explain:"Tidak semua pola berguna. Pola yang berharga membantu memprediksi atau menyelesaikan sesuatu yang kita pedulikan.",hint:"Apakah pola ini membantumu menjawab soal, atau hanya fakta iseng?"},
{n:72,type:"mcq",micro:"Analogi berlebihan",q:"Terus-menerus memaksakan analogi ('semua masalah itu seperti perang') berisiko...",options:["Tidak ada risiko","Membuat kamu ahli strategi","Membingkai setiap masalah dengan cara yang sama sehingga kamu buta terhadap pendekatan lain (kerja sama, negosiasi, desain ulang)"],answer:2,explain:"Satu analogi favorit yang dipakai untuk segala hal mempersempit cara berpikir. Ragam analogi menjaga fleksibilitas.",hint:"Kalau semua terlihat seperti 'perang', solusi apa yang mungkin kamu lewatkan?"},
{n:73,type:"tf",micro:"Pola membutuhkan penjelasan untuk dipercaya penuh",q:"Benar atau Salah: Pola yang punya penjelasan mekanisme yang jelas (mengapa ia terjadi) umumnya lebih bisa diandalkan untuk prediksi daripada pola yang hanya 'kebetulan cocok' tanpa alasan.",answer:true,explain:"Pola dengan sebab yang dipahami cenderung bertahan; pola tanpa penjelasan bisa jadi kebetulan yang akan pecah.",hint:"Mana yang lebih kamu percayai: pola yang kamu tahu penyebabnya, atau pola yang 'entah kenapa cocok'?"},
{n:74,type:"mcq",micro:"Menemukan pola vs memaksakan pola",q:"Perbedaan antara 'menemukan pola yang benar-benar ada' dan 'memaksakan pola':",options:["Pola yang ditemukan lolos uji pada data baru dan sering punya penjelasan; pola yang dipaksakan gagal saat diuji atau butuh pengecualian terus-menerus","Tidak ada bedanya","Pola yang dipaksakan lebih menarik"],answer:0,explain:"Kalau kamu harus terus menambah 'kecuali...' untuk mempertahankan pola, kemungkinan polanya tidak nyata.",hint:"Berapa banyak pengecualian sebelum sebuah 'aturan' berhenti berguna?"},
{n:75,type:"mcq",micro:"Analogi untuk komunikasi vs untuk penalaran",q:"Sebuah analogi bisa bagus untuk MENJELASKAN ide ke orang lain tapi buruk untuk MENARIK KESIMPULAN baru. Ini karena...",options:["Menjelaskan dan menyimpulkan sebenarnya sama saja, sehingga analogi yang bagus untuk menjelaskan pasti otomatis bagus juga untuk menyimpulkan hal baru","Untuk menjelaskan, cukup menyoroti satu kesamaan yang sudah kamu pahami; untuk menyimpulkan, kamu bergantung pada kesamaan yang belum tentu berlaku","Analogi tidak pernah dipakai dalam penalaran sungguhan, sehingga ia hanya hiasan kalimat yang tidak boleh dipakai untuk menjelaskan maupun menyimpulkan"],answer:1,explain:"Analogi aman sebagai alat bantu penjelasan; sebagai dasar kesimpulan, ia harus diperiksa apakah kesamaannya benar-benar relevan.",hint:"Apakah 'A seperti B' membuktikan sesuatu tentang A, atau hanya membantu membayangkannya?"},
{n:76,type:"mcq",micro:"Pola musiman vs tren",q:"Penjualan payung naik tiap musim hujan lalu turun. Kalau tahun ini penjualan Oktober lebih tinggi dari September, menyimpulkan 'bisnis payung sedang tumbuh pesat' bisa keliru karena...",options:["Payung memang laris","Datanya bohong","Itu mungkin hanya pola musiman (masuk musim hujan), bukan pertumbuhan jangka panjang"],answer:2,explain:"Membedakan pola berulang (musiman) dari tren jangka panjang penting agar tidak salah menyimpulkan.",hint:"Bandingkan dengan Oktober tahun-tahun sebelumnya, bukan hanya dengan September."},
{n:77,type:"tf",micro:"Tidak semua masalah punya analogi berguna",q:"Benar atau Salah: Mencari analogi selalu merupakan langkah pertama terbaik untuk setiap masalah, tanpa kecuali.",answer:false,explain:"Analogi adalah salah satu alat, bukan satu-satunya. Untuk sebagian masalah, analisis langsung, eksperimen, atau dekomposisi lebih tepat.",hint:"Apakah setiap masalah paling baik didekati dengan 'ini mirip apa ya?'"},
{n:78,type:"mcq",micro:"Pola dan pengecualian",q:"Kamu menemukan pola 'semua bilangan prima itu ganjil'. Menemukan bahwa 2 adalah prima dan genap berarti...",options:["Pola aslinya salah dan perlu diperbaiki: 'semua prima KECUALI 2 adalah ganjil'","Berarti 2 sebenarnya bukan bilangan prima, sehingga pola semula tetap benar dan tidak perlu diperbaiki sama sekali","Pengecualian seperti itu boleh diabaikan saja, karena satu contoh tidak cocok tidak mungkin membuat pola salah"],answer:0,explain:"Satu contoh tandingan (counterexample) sudah cukup untuk menunjukkan sebuah pola umum tidak berlaku sepenuhnya, dan memaksa perbaikan.",hint:"Berapa contoh tandingan yang dibutuhkan untuk mematahkan klaim 'semua'?"},
{n:79,type:"mcq",micro:"Menyeimbangkan pola dan kehati-hatian",q:"Sikap paling sehat terhadap pola yang baru kamu temukan:",options:["Abaikan semua pola","Pakai sebagai dugaan kerja yang berguna, sambil tetap terbuka bahwa ia bisa salah atau punya batas","Percaya 100% dan berhenti memeriksa"],answer:1,explain:"Pola adalah alat prediksi yang kuat bila dipakai dengan kesadaran akan ketidakpastiannya.",hint:"Antara 'percaya buta' dan 'menolak semua', di mana posisi yang bijak?"},
{n:80,type:"open",micro:"Membongkar analogi yang menyesatkan",q:"Sebuah iklan bilang: 'Tubuhmu seperti mesin mobil — kalau kamu isi bahan bakar premium (suplemen kami), performamu maksimal.' Jelaskan minimal dua cara analogi ini menyesatkan, dan apa yang perlu diperiksa sebelum percaya.",explain:"Jawaban baik mengenali di mana analogi mesin-tubuh pincang (kompleksitas, penyesuaian diri, tidak ada 'aditif ajaib') dan menyebut pemeriksaan bukti yang diperlukan.",hint:"Di mana tubuh manusia BERBEDA dari mesin, dan apa yang analogi ini buat kamu abaikan?",sample:"(1) Tubuh manusia jauh lebih rumit dan menyesuaikan diri daripada mesin — ia tidak sekadar 'membakar bahan bakar', dan kelebihan 'bahan bakar' tidak otomatis menambah performa (bisa malah membebani). (2) 'Premium' pada bensin adalah standar yang jelas; klaim suplemen 'premium' belum tentu punya bukti. (3) Analogi menyembunyikan bahwa tubuh butuh gizi seimbang, tidur, dan latihan — bukan satu 'aditif ajaib'. Yang perlu diperiksa: adakah penelitian independen bahwa suplemen ini benar-benar meningkatkan sesuatu yang terukur; apa kandungannya; apakah pola makan biasa sudah mencukupi."},
{n:81,type:"mcq",micro:"Membangun solusi dari beberapa pola",q:"Merancang jadwal piket adil untuk 6 kelompok, 5 hari: kamu memakai pola 'rotasi siklus' (dari pola manik-manik) DAN pola 'bagi rata' (dari pembagian). Menggabungkan pola berarti...",options:["Hanya boleh memakai satu pola saja dalam satu masalah, sehingga pola lain harus dibuang meskipun berguna","Pola tidak bisa digabung, karena setiap pola hanya bisa dipakai pada jenis masalah yang sama persis dengannya","Mengambil ide struktural dari beberapa pola yang kamu kenal untuk menyusun solusi masalah baru"],answer:2,explain:"Solusi masalah nyata sering merupakan gabungan dari beberapa pola/prinsip yang masing-masing sudah kamu kuasai.",hint:"Bisakah kamu memakai 'rotasi' untuk keadilan antar hari dan 'bagi rata' untuk jumlah giliran?"},
{n:82,type:"mcq",micro:"Analogi untuk masalah yang belum ada solusinya",q:"Tim ingin mengurangi antrean panjang di loket pendaftaran acara. Analogi dari 'antrean bank modern' (nomor antrean + beberapa loket + papan pemanggil) menyarankan...",options:["Bagi pendaftaran jadi beberapa jalur paralel + sistem nomor, sehingga orang tidak berdiri lama dan bisa menunggu sambil duduk","Tutup pendaftaran","Buat antrean lebih panjang"],answer:0,explain:"Meminjam struktur solusi dari domain yang sudah menyelesaikan masalah serupa (bank, bandara) adalah transfer yang produktif.",hint:"Bagaimana bank menangani banyak orang yang perlu dilayani tanpa antrean berdiri yang panjang?"},
{n:83,type:"tf",micro:"Menyederhanakan adalah kunci masalah besar",q:"Benar atau Salah: Untuk masalah besar yang membingungkan, menyelesaikan dulu versi yang jauh lebih sederhana sering menjadi cara paling cepat menemukan pendekatan yang benar.",answer:true,explain:"Versi sederhana mengungkap struktur inti tanpa gangguan detail, dan pendekatan yang berhasil di sana biasanya berkembang ke versi penuh.",hint:"Bagaimana ilmuwan sering memulai mempelajari sistem rumit?"},
{n:84,type:"mcq",micro:"Pola dalam data untuk mengambil keputusan",q:"Data peminjaman perpustakaan menunjukkan pola: buku komik dipinjam 5x lebih sering dari buku lain, dan lonjakan terjadi tiap awal bulan (uang saku baru → ?). Keputusan berbasis pola:",options:["Abaikan datanya","Tambah koleksi komik dan jadwalkan pameran buku baru di awal bulan saat minat sedang tinggi","Hentikan peminjaman komik"],answer:1,explain:"Pola dalam data (jenis populer + waktu puncak minat) langsung menyarankan tindakan yang memanfaatkannya.",hint:"Manfaatkan apa yang sudah disukai orang, dan waktu saat mereka paling tertarik."},
{n:85,type:"order",micro:"Strategi pola untuk masalah tak dikenal",q:"Urutkan langkah menghadapi masalah yang benar-benar baru memakai pola & analogi.",items:["Pahami masalah: apa strukturnya, apa yang dicari","Tanya: 'masalah apa yang pernah kuselesaikan yang strukturnya mirip?' dan/atau buat versi yang jauh lebih sederhana","Terapkan cara dari masalah analog / temukan pola dari versi sederhana","Periksa perbedaan antara masalah analog dan masalah asli, sesuaikan, lalu uji jawabannya"],answer:[0,1,2,3],explain:"Pahami struktur → cari analog atau sederhanakan → transfer cara/pola → sesuaikan untuk perbedaan & uji.",hint:"Kamu perlu memahami struktur sebelum bisa mencari yang mirip."},
{n:86,type:"mcq",micro:"Pola dalam kesalahan kolektif",q:"Guru melihat 25 dari 30 siswa membuat kesalahan yang SAMA PERSIS pada soal pecahan. Pola ini menunjukkan...",options:["Dua puluh lima siswa itu hanya ceroboh dan tidak teliti, sehingga cukup diminta lebih berhati-hati saat mengerjakan","Soalnya memang terlalu sulit untuk anak seusia mereka, sehingga soal itu sebaiknya dihapus dari buku pelajaran","Ada satu kesalahpahaman bersama (mungkin dari cara materi diajarkan), bukan 25 kesalahan acak yang terpisah — perbaiki akarnya sekali"],answer:2,explain:"Pola kesalahan yang identik pada banyak orang menunjuk ke penyebab bersama yang bisa diperbaiki di satu titik.",hint:"Kalau semua salah dengan cara yang sama, apa yang sama-sama mereka pelajari?"},
{n:87,type:"mcq",micro:"Analogi yang menghasilkan hipotesis",q:"Peneliti menyadari 'penyebaran rumor di sekolah' berperilaku seperti 'penyebaran penyakit menular'. Analogi ini berguna karena...",options:["Menyarankan hipotesis yang bisa diuji: rumor menyebar lebih cepat lewat orang yang banyak kenalan; membatasi 'kontak' informasi memperlambatnya","Rumor adalah penyakit","Tidak berguna"],answer:0,explain:"Analogi struktural yang kuat memindahkan seluruh kerangka pemikiran (model penularan) ke domain baru, menghasilkan prediksi yang bisa diuji.",hint:"Apa yang bisa dipinjam dari cara ahli memahami penyebaran penyakit?"},
{n:88,type:"tf",micro:"Generalisasi tetap perlu diuji",q:"Benar atau Salah: Begitu sebuah solusi digeneralisasi menjadi aturan umum, aturan itu langsung bisa dipercaya untuk semua kasus tanpa perlu diuji lagi.",answer:false,explain:"Generalisasi memperbesar nilai kerja kita, tapi aturan itu tetap perlu diuji pada kasus yang belum dipakai membuatnya — tanpa pengujian, satu kesalahan bisa menyebar ke banyak kasus sekaligus.",hint:"Apa risiko sebuah aturan umum yang ternyata salah?"},
{n:89,type:"mcq",micro:"Ketika tidak ada analog",q:"Kamu benar-benar tidak menemukan masalah analog untuk masalahmu. Langkah selanjutnya:",options:["Menyerah","Beralih ke strategi lain: sederhanakan drastis, coba kasus kecil, dekomposisi, atau bereksperimen — dan bangun pemahaman dari sana","Memaksakan analogi yang jelas tidak cocok"],answer:1,explain:"Analogi hanya satu alat. Ketiadaan analog berarti memakai alat lain, bukan berhenti.",hint:"Strategi apa lagi yang bisa membuka masalah yang benar-benar baru?"},
{n:90,type:"mcq",micro:"Pola yang berlaku sampai titik tertentu",q:"Melipat kertas: tiap lipatan menggandakan ketebalan. Pola ini akurat untuk beberapa lipatan pertama, tapi 'setelah ~7 lipatan tidak bisa dilipat lagi' menunjukkan...",options:["Penggandaan itu salah","Kertasnya jelek","Pola matematis (penggandaan) benar, tapi kendala fisik nyata membatasi seberapa jauh ia berlaku"],answer:2,explain:"Pola bisa benar secara matematis namun dibatasi oleh kenyataan fisik. Mengetahui kedua sisi penting untuk prediksi yang berguna.",hint:"Apakah aturan 'ketebalan berlipat ganda' berhenti berlaku, atau hanya kemampuan melipatnya yang habis?"},
{n:91,type:"mcq",micro:"Membedakan pola sebab dari pola waktu",q:"'Setiap kali klub kami ganti ketua, jumlah anggota naik.' Sebelum menyimpulkan 'ganti ketua menambah anggota', periksa...",options:["Apakah kenaikan itu mungkin karena hal lain yang kebetulan bersamaan (awal semester, promosi, tren), dan apakah polanya cukup banyak kejadiannya","Tidak perlu memeriksa apa pun lagi, karena kenaikan anggota yang terjadi berulang pasti disebabkan oleh pergantian ketua dan bukan oleh hal lain","Langsung ganti ketua lagi secepatnya, karena itu terbukti cara yang paling pasti menambah anggota klub setiap kali jumlahnya mulai turun lagi"],answer:0,explain:"Pola berulang bisa disebabkan faktor lain yang selalu muncul bersamaan. Butuh lebih banyak kasus dan pemeriksaan penyebab alternatif.",hint:"Apa lagi yang berubah setiap kali ketua diganti?"},
{n:92,type:"tf",micro:"Analogi bagus butuh pemetaan yang jelas",q:"Benar atau Salah: Analogi menjadi paling berguna ketika kamu bisa memetakan bagian-bagiannya secara eksplisit (bagian A dari masalah lama sesuai dengan bagian A' dari masalah baru).",answer:true,explain:"Pemetaan eksplisit mengubah analogi kabur menjadi alat yang tepat — dan menunjukkan di mana pemetaan itu gagal (perbedaan penting).",hint:"Mana yang lebih berguna: 'ini agak mirip itu', atau 'bagian X di sini = bagian Y di sana'?"},
{n:93,type:"mcq",micro:"Pola untuk memperkirakan tanpa menghitung penuh",q:"Panitia perlu perkiraan cepat: 'kalau 3 orang melipat 60 undangan dalam 20 menit, berapa lama 5 orang melipat 200 undangan?' Pakai pola laju:",options:["Tidak bisa diperkirakan","3 orang → 60/20 = 3 undangan/menit total, jadi 1 orang = 1/menit; 5 orang = 5/menit; 200 ÷ 5 = 40 menit","200 menit"],answer:1,explain:"Mengenali pola 'laju sebanding dengan jumlah orang' memungkinkan perkiraan cepat lewat perbandingan.",hint:"Berapa undangan per menit per orang, lalu skala ke 5 orang?"},
{n:94,type:"open",micro:"Pola & analogi untuk masalah kompleks",q:"Masalah: 'Informasi penting (perubahan jadwal, tugas) sering tidak sampai ke semua siswa kelas.' Lakukan: (1) identifikasi struktur masalah, (2) sebutkan 1–2 masalah analog dari bidang lain + pemetaannya, (3) cari pola dalam KAPAN/BAGAIMANA informasi gagal sampai, (4) usulkan solusi yang menggabungkan wawasan dari (2) dan (3), (5) sebutkan satu perbedaan yang membuat analogimu tidak sempurna.",explain:"Jawaban baik: mengenali struktur 'satu ke banyak dengan kebocoran', memetakan analog dengan jelas, menemukan pola kegagalan spesifik, menggabungkannya menjadi solusi berlapis, dan menyebut batas analogi.",hint:"Masalah 'menyampaikan info ke banyak orang tanpa ada yang terlewat' sudah dipecahkan di banyak bidang — pinjam strukturnya.",sample:"(1) Struktur: satu sumber informasi → banyak penerima → sebagian penerima terlewat; mirip 'penyiaran ke jaringan yang tidak semua simpulnya terhubung'. (2) Analog: (a) sistem estafet pesan darurat / pohon telepon — tiap orang bertanggung jawab meneruskan ke 2 orang berikutnya; pemetaan: guru = pusat, ketua kelompok = simpul cabang, anggota = daun. (b) papan pengumuman + notifikasi ganda (aplikasi + tempel fisik) seperti bandara mengumumkan lewat layar DAN suara. (3) Pola kegagalan: paling sering saat pengumuman lisan mendadak di akhir pelajaran (siswa sudah tidak fokus / keburu keluar), dan saat hanya lewat satu kanal (grup chat yang tidak semua aktif). (4) Solusi: tetapkan 5 ketua kelompok; tiap pengumuman ditulis di papan kelas + dikirim ke ketua kelompok yang wajib konfirmasi 'sudah diteruskan'; hindari pengumuman penting hanya lisan di menit terakhir. (5) Perbedaan: tidak seperti pohon telepon darurat, di kelas orang bisa saling bertemu langsung setiap hari, jadi konfirmasi tatap muka keesokan harinya bisa jadi lapisan pengaman tambahan."},
{n:95,type:"mcq",micro:"Menilai kekuatan sebuah analogi",q:"Analogi paling bisa diandalkan untuk menarik kesimpulan bila...",options:["Kedua hal terlihat mirip secara penampilan luar, walaupun cara kerja dan hubungan antar bagiannya sangat berbeda","Analogi itu terdengar puitis dan indah, sehingga orang yang mendengarnya langsung yakin bahwa kesimpulannya benar","Kesamaan strukturalnya banyak dan relevan dengan pertanyaan, perbedaannya sedikit dan tidak penting untuk pertanyaan itu"],answer:2,explain:"Kekuatan analogi diukur dari banyaknya kesamaan yang relevan dan sedikitnya perbedaan yang penting untuk kesimpulan yang ingin ditarik.",hint:"Bukan soal mirip di permukaan — soal apakah kemiripannya menyangkut hal yang sedang kamu tanyakan."},
{n:96,type:"mcq",micro:"Pola dan otomatisasi",q:"Setelah kamu menemukan pola stabil dalam tugas rutin (misalnya urutan langkah menyiapkan lab tiap Senin), langkah cerdas:",options:["Ubah jadi checklist/prosedur tetap sehingga tidak perlu memikirkannya ulang tiap kali dan lebih sedikit yang terlewat","Sengaja lakukan berbeda tiap minggu","Rahasiakan polanya"],answer:0,explain:"Pola yang andal pada tugas berulang layak 'dibekukan' menjadi prosedur — menghemat pikiran dan mengurangi kesalahan.",hint:"Untuk apa memecahkan masalah yang sama setiap Senin?"},
{n:97,type:"tf",micro:"Pola & analogi adalah keterampilan yang bisa dilatih",q:"Benar atau Salah: Semakin banyak masalah yang kamu selesaikan dan tinjau, semakin baik kamu mengenali pola dan menemukan analogi yang berguna.",answer:true,explain:"Kemampuan ini tumbuh dari pengalaman: setiap masalah menambah 'pola tersimpan' dan mempertajam mata untuk kesamaan struktural.",hint:"Mengapa orang berpengalaman lebih cepat berkata 'oh, ini seperti...'?"},
{n:98,type:"mcq",micro:"Menggabungkan semua alat",q:"Pola & analogi bekerja paling baik bila digabung dengan...",options:["Menghindari strategi lain","Memahami masalah dengan baik, dekomposisi, pemeriksaan hasil, dan kesediaan mengganti pendekatan","Hanya menebak"],answer:1,explain:"Pola & analogi adalah bagian dari kotak alat pemecahan masalah, bukan pengganti pemahaman, perencanaan, dan verifikasi.",hint:"Apakah satu alat cukup untuk semua masalah?"},
{n:99,type:"mcq",micro:"Ringkasan: pola & analogi",q:"Rangkuman paling tepat:",options:["Pola dan analogi selalu memberi jawaban yang pasti benar dalam setiap keadaan, sehingga hasilnya tidak perlu lagi diuji ataupun diperiksa batasnya, dan keduanya cukup dipakai sekali lalu dipercaya selamanya","Pola dan analogi hanya berguna untuk pelajaran matematika di sekolah, dan tidak bisa dipakai untuk memecahkan masalah sehari-hari di rumah maupun di kelas, karena keduanya hanya berlaku untuk deret angka saja","Pola membantu memprediksi dari aturan yang berulang; analogi membantu menyelesaikan masalah baru dengan meminjam struktur masalah lama — keduanya kuat tetapi harus diuji dan diperiksa batasnya"],answer:2,explain:"Pola: aturan berulang untuk prediksi. Analogi: transfer struktur antar masalah. Keduanya alat dugaan yang butuh pengujian dan kesadaran akan batas.",hint:"Gabungkan: prediksi dari aturan + transfer struktur + selalu diuji."},
{n:100,type:"open",micro:"Kapstone: pola & analogi dari nol",q:"Pilih masalah nyata yang kamu hadapi. Lakukan: (1) nyatakan masalah & strukturnya, (2) sederhanakan drastis dan selesaikan versi kecilnya — catat pola yang muncul, (3) cari satu masalah analog dari kehidupan/bidang lain + pemetaan bagian-bagiannya, (4) susun solusi yang menggabungkan pola dari (2) dan wawasan dari (3), (5) uji solusi pada satu situasi baru, (6) sebutkan di mana pola/analogimu punya batas.",explain:"Kapstone menyatukan: analisis struktur, penyederhanaan untuk menemukan pola nyata (estimasi meleset), analogi terpeta (antrean), solusi gabungan, pengujian, dan pengakuan batas analogi.",hint:"Kerjakan keenam bagian; pastikan pola di (2) berasal dari data nyata, bukan tebakan.",sample:"Contoh ringkas — Masalah: waktu mengerjakan PR tidak cukup, sering begadang. (1) Struktur: banyak tugas + waktu tetap + estimasi meleset → penumpukan (mirip 'antrean dengan laju masuk > laju keluar'). (2) Versi kecil: catat waktu nyata 3 jenis PR selama seminggu → pola: PR yang kukira 20 menit rata-rata 40 menit; PR menulis paling meleset. (3) Analog: manajemen antrean di kasir — kalau kedatangan > kecepatan layani, antrean tumbuh; solusinya: kurangi kedatangan (kurangi beban), tambah 'kasir' (blok waktu / bantuan), atau percepat layanan (teknik lebih efisien). Pemetaan: tugas = pelanggan, waktu belajar = kasir, penumpukan = antrean. (4) Solusi: (a) mulai PR menulis lebih awal & pecah jadi 2 sesi (percepat layanan via dekomposisi); (b) blok 30 menit tetap tiap sore khusus PR (tambah kapasitas terjadwal); (c) estimasi × 1,8 berdasarkan pola nyata; (d) kalau menumpuk, kerjakan yang wajib dulu. (5) Uji minggu berikutnya: begadang berkurang dari 3 malam jadi 1. (6) Batas: analogi antrean tidak menangkap bahwa kualitas kerja turun saat lelah — jadi 'menambah jam malam' bukan solusi setara dengan 'menambah kasir'."},
];
